import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"MiniMax Agent 实战手册","description":"已经能登录网页后再看。每个配方只解决一个问题，步骤必须能在官方页找到依据。","frontmatter":{"title":"MiniMax Agent 实战手册","description":"已经能登录网页后再看。每个配方只解决一个问题，步骤必须能在官方页找到依据。","domain":"product","tags":["coding-agent"],"role":"cookbook"},"headers":[],"relativePath":"zh/products/minimax-agent/minimax-agent-cookbook.md","filePath":"zh/products/minimax-agent/minimax-agent-cookbook.md","lastUpdated":1787110548000}'),i={name:"zh/products/minimax-agent/minimax-agent-cookbook.md"};function o(s,t,l,d,p,m){return n(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="minimax-agent-实战手册" tabindex="-1">MiniMax Agent 实战手册 <a class="header-anchor" href="#minimax-agent-实战手册" aria-label="Permalink to &quot;MiniMax Agent 实战手册&quot;">​</a></h1><p>面向已经打开 <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a> 的读者。每个配方先写目标，再写步骤，最后写坑。</p><p>基础安装与模式说明在 <a href="./minimax-agent.html">教程</a>。本页不重复。</p><h2 id="_1-写一份带出处的调研报告" tabindex="-1">1. 写一份带出处的调研报告 <a class="header-anchor" href="#_1-写一份带出处的调研报告" aria-label="Permalink to &quot;1. 写一份带出处的调研报告&quot;">​</a></h2><p><strong>目标：</strong> 得到一份能转给同事的 Markdown / PDF，而不是聊天记录。</p><p><strong>何时用：</strong> Pro。资料要并行核验时再开 Agent Team。</p><p><strong>步骤：</strong></p><ol><li>切到 Pro。</li><li>第一句写清范围、禁用源、交付格式。</li><li>要求列出每条结论对应的官方 URL。</li><li>如果任务同时要 HTML / PPT 第二份交付，在同一条消息里写完，避免中途改需求污染上下文。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于 2026 年官方页面，整理 MiniMax Agent 能做什么、不能做什么。</span></span>
<span class="line"><span>允许来源：minimaxi.com、agent.minimaxi.com、agent.minimax.io。</span></span>
<span class="line"><span>禁止：转载站、评测博客、社交截图。</span></span>
<span class="line"><span>交付 Markdown 报告，每条论断后面跟原文链接。</span></span></code></pre></div><p><strong>坑：</strong> 单 Agent 会在完成一半时停下来汇报。官方 <a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team</a> 把这写成上下文焦虑。要完整交付就写「未完成验收条件不许结束」，或开 Team。</p><h2 id="_2-做-ppt-报告-网页-而不是只要正文" tabindex="-1">2. 做 PPT / 报告 / 网页，而不是只要正文 <a class="header-anchor" href="#_2-做-ppt-报告-网页-而不是只要正文" aria-label="Permalink to &quot;2. 做 PPT / 报告 / 网页，而不是只要正文&quot;">​</a></h2><p><strong>目标：</strong> 拿到可下载的幻灯片、文档或可打开的页面。</p><p><strong>依据：</strong> <a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 新闻</a> 把 PPT、报告撰写、网页制作列为 Pro 场景。<a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a> 展示过带音频的教程和前端动画页面。</p><p><strong>步骤：</strong></p><ol><li>Pro。</li><li>指定页数、受众、格式（HTML / PDF / PPTX / DOCX）。</li><li>先要大纲，确认后再出成片。Agent Team 文把办公文档拆成 Planner → Writer → Formatter → Evaluator。</li><li>需要固定版式时，先到 <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">技能市场</a> 看有没有演示文稿 / DOCX / PowerPoint 技能。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给前端工程师写一份 8 页产品介绍。</span></span>
<span class="line"><span>受众：已经会用 Cursor，第一次听说 MiniMax Agent。</span></span>
<span class="line"><span>先给大纲，我确认后再生成 HTML 幻灯片，并提供 PDF 导出。</span></span>
<span class="line"><span>不要写 MiniMax Code 的安装步骤。</span></span></code></pre></div><p><strong>坑：</strong> 不要在 Lightning 里做这件事。官方把这类任务放在 Pro。</p><h2 id="_3-判断要不要开-agent-team" tabindex="-1">3. 判断要不要开 Agent Team <a class="header-anchor" href="#_3-判断要不要开-agent-team" aria-label="Permalink to &quot;3. 判断要不要开 Agent Team&quot;">​</a></h2><p><strong>目标：</strong> 少浪费一轮「单 Agent 写完但交不了货」。</p><table tabindex="0"><thead><tr><th>信号</th><th>动作</th></tr></thead><tbody><tr><td>只要一段回答</td><td>不开 Team，Lightning 即可</td></tr><tr><td>要多源研究 + 核验 + 合成</td><td>开 Team</td></tr><tr><td>IM 里发任务、人等不及最终结果</td><td>开 Team。官方写主 Agent 先秒回，后台跑</td></tr><tr><td>改错别字、换一句文案</td><td>不开。官方说这类更便宜走单 Agent</td></tr></tbody></table><p><strong>步骤：</strong> 首页打开 <strong>Agent 团队</strong>，再发任务。不要同时塞三个互不相关的大目标。</p><p><strong>坑：</strong> Team 有交接成本。官方技术文把交接、共享、聚合写成新成本。目标含糊会让 Worker 和 Verifier 空转。</p><h2 id="_4-先装技能-再开始重复劳动" tabindex="-1">4. 先装技能，再开始重复劳动 <a class="header-anchor" href="#_4-先装技能-再开始重复劳动" aria-label="Permalink to &quot;4. 先装技能，再开始重复劳动&quot;">​</a></h2><p><strong>目标：</strong> 第二次做同类交付时不要从零描述流程。</p><p><strong>步骤：</strong></p><ol><li>打开 <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skills</a>。</li><li>用任务类型搜（演示文稿、研究报告、Excel、网页）。</li><li>安装后再在对话里引用该技能。</li><li>市场没有、但你已经跑通两次的流程，再考虑自定义或从 GitHub 导入。官方市场文案支持这两条。</li></ol><p><strong>坑：</strong></p><ul><li>技能名单和「uses」计数每天都可能变，不要把本页截图当目录。</li><li>Code 插件市场（金融数据、企查查、Office、Notion 等）写在桌面端更新说明里，不是本配方的安装步骤。</li></ul><h2 id="_5-网页-agent-做不了时-换门-不要硬凑" tabindex="-1">5. 网页 Agent 做不了时，换门，不要硬凑 <a class="header-anchor" href="#_5-网页-agent-做不了时-换门-不要硬凑" aria-label="Permalink to &quot;5. 网页 Agent 做不了时，换门，不要硬凑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你真正要的</th><th>去哪</th><th>不要做什么</th></tr></thead><tbody><tr><td>本机仓库、终端、diff、Git</td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">MiniMax Code</a></td><td>不要在网页 Agent 里假装有工作区面板</td></tr><tr><td>一条视频</td><td><a href="https://hailuoai.com/" target="_blank" rel="noreferrer">Hailuo</a></td><td>不要为了「也能生视频」强行走 Agent</td></tr><tr><td>配音 / 音乐</td><td><a href="https://www.minimaxi.com/audio" target="_blank" rel="noreferrer">Audio</a></td><td>不要把 Audio 当 Agent 模式</td></tr><tr><td>角色扮演</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">星野</a> / <a href="https://www.talkie-ai.com/" target="_blank" rel="noreferrer">Talkie</a></td><td>不要把陪伴产品写成工作台</td></tr><tr><td>分镜成片画布</td><td><a href="https://design.minimaxi.com/" target="_blank" rel="noreferrer">Design</a></td><td>不要把 Hub 旧名当成 Agent</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./minimax-agent.html">教程</a></li><li><a href="./minimax-agent-cheatsheet.html">速查表</a></li><li><a href="./minimax-agent-glossary.html">术语表</a></li></ul>`,32)])])}const f=a(i,[["render",o]]);export{x as __pageData,f as default};
